import type { MetadataRoute } from 'next';

/** Web app manifest: name, theme colours and the official GrowthPrint icons (generated by scripts/brand). */
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: 'GrowthPrint',
    short_name: 'GrowthPrint',
    description: 'Your AI-native technology partner. Build smarter. Scale with confidence.',
    start_url: '/',
    display: 'standalone',
    background_color: '#080710',
    theme_color: '#080710',
    icons: [
      { src: '/brand/icons/icon-192.png', sizes: '192x192', type: 'image/png' },
      { src: '/brand/icons/icon-512.png', sizes: '512x512', type: 'image/png' },
      { src: '/brand/icons/icon-maskable-512.png', sizes: '512x512', type: 'image/png', purpose: 'maskable' },
    ],
  };
}
